from pathlib import Path
import json,hashlib
import pandas as pd
B=Path(__file__).resolve().parent;P=B.parent/'unpacked/interchangeability_20261020'
f=pd.read_csv(P/'forward/features_train.csv.gz').set_index('worker_id');fw=pd.read_csv(P/'forward/worker_labels.csv.gz');fid='F20_highQ23_T_qK2';z=fw[fw.method_id.eq(fid)].set_index('worker_id');rid='R_directswap_geometry_partition_b2_K2__ordinary_new__mixed_history_v1';rm=json.load(open(P/'reverse/mixed_fit/METHOD_MANIFEST.json'))[rid];rl={w:c for c,ws in rm['classes'].items() for w in ws};rows=[]
for w,r in f.sort_index().iterrows():
 x=z.loc[w];rc=rl.get(w,'unknown');fc=x.class_id if x.known else 'unknown'
 rows.append({'worker_id':w,'source_origin':r.person_origin,'research_only':True,'Rnew2_geometry_quality_class':rc,'Rnew2_known':w in rl,'Rnew2_reason':'supported_history_ordinary_manual_new_source' if w in rl else 'outside_new_source_domain','Rnew2_measured_condition':'ordinary Manual; exchanged workers new-source; fixed same image/reference/background; historical geometry-risk partition','F01_efficiency_class':fc,'F01_known':bool(x.known),'F01_reason':str(x.reason),'F01_measured_condition':'history highQ23 eligible population; source-specific task-adjusted log-time quantile; ordinary Manual','F01_efficiency_description':{'C01':'lower source-normalized historical log time','C02':'higher source-normalized historical log time'}.get(fc,'not assigned; no low-quality inference'),'F01_history_eligible_population':bool(x.eligible_population),'working_use':'conditional research reference; not universal interchangeability or personnel performance decision'})
out=pd.DataFrame(rows);assert len(out)==60 and out.worker_id.is_unique and out.Rnew2_known.sum()==35 and out.F01_known.sum()==23
out.to_csv(B/'RESEARCH_WORKING_LABELS_60.csv',index=False)
classes={'Rnew2_geometry_quality':{'method_id':rid,'classes':rm['classes'],'conditions':'ordinary Manual, new-source exchanged blocks; same image/reference/core; no claim for Semi/scope/doorway or arbitrary n,m','interpretation':'geometry-risk-defined partition substantially correlated with historical Q; C01 higher historical Q on average, C02 lower on average, not guaranteed ability rank'},'F01_efficiency':{'method_id':fid,'classes':{c:sorted(z.index[z.known&z.class_id.eq(c)].tolist()) for c in sorted(z[z.known].class_id.unique())},'conditions':'history highQ23 population, ordinary Manual; primary frozen direction n13,m2,C02 toC01; source matched and Q-close supports reported separately','interpretation':'source/task-adjusted historical time classes; faster/slower is relative within source, not absolute cross-source seconds or causal productivity'}}
(B/'RESEARCH_WORKING_LABELS_SCHEMA.json').write_text(json.dumps({'version':'research_only_20261020','rows':60,'independent_columns_not_cartesian_hierarchy':True,'unknown_policy':'outside domain or unsupported remains unknown, never imputed as low quality','classes':classes,'csv_sha256':hashlib.sha256((B/'RESEARCH_WORKING_LABELS_60.csv').read_bytes()).hexdigest()},indent=2))
lines=['# 人员分类代码审计与有限追加实验结论','','## 结论','','原始 Rnew2 的35人、21/14二类已从原始输入及新重建的历史融合结果独立复算，完整标签与10次留一建筑标签全部一致，平均 ARI=0.95496594。这个 ARI 说明划分对删除历史建筑较稳定，不等于所有同类人员均可互换。','','新增的连续角点距离 m1 学习，及专门使用真实多人块结果的 m2 学习，都没有建立优于现有有效基线的实用通用分类。冻结的 legacy meanK3 在共享 m2 测试上未优于 Rnew2；新的直接 m2 K2/K3 在历史留建筑验证中也同时输给 Q 与 Rnew2，而且完整有效距离覆盖与角点数量变化风险更差。因此不采用新模型来宣称研究目标已完成，也不继续搜索直到出现好看结果。','','## 可交付的研究工作标签','','RESEARCH_WORKING_LABELS_60.csv 覆盖全部60人，每人保留两个独立字段，不能拼成已经验证的统一层级：','','1. Rnew2_geometry_quality_class：35名新来源人员的几何/质量相关二类。其余25人属于域外，不填为差或低质量。','2. F01_efficiency_class：历史 highQ23 人群内的效率二类，23人（12/11）。其余人员保留原始“不属于适用人群/支持不足”原因。时间量为来源内、任务调整后的相对对数时间，不能解释成跨来源绝对速度或因果生产率。','','### Rnew2 精确成员']
for c,ws in rm['classes'].items():lines.append('- '+c+'（'+str(len(ws))+'人）：'+', '.join(ws))
